import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"Visitor","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/visitor.md","filePath":"03-developer/models/visitor.md"}`),a={name:`03-developer/models/visitor.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="visitor" tabindex="-1">Visitor <a class="header-anchor" href="#visitor" aria-label="Permalink to “Visitor”">​</a></h1><p>The <code>Visitor</code> model is used to record visitor information and collect data about their browser, operating system, referral source, and visited page. This information can be used to display site traffic statistics and analyze visitors&#39; overall behavior.</p><h2 id="data-structure" tabindex="-1">Data structure <a class="header-anchor" href="#data-structure" aria-label="Permalink to “Data structure”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Unique record ID</td></tr><tr><td><code>ip</code></td><td>VARCHAR(45)</td><td>No</td><td>Visitor&#39;s IP address</td></tr><tr><td><code>visit</code></td><td>INT UNSIGNED</td><td>No</td><td>Number of visits recorded for the IP within the time period used by the system; defaults to <code>1</code></td></tr><tr><td><code>browser</code></td><td>ENUM(&#39;Firefox&#39;, &#39;FirFox&#39;, &#39;Chrome&#39;, &#39;Edge&#39;, &#39;Opera&#39;, &#39;Brave&#39;, &#39;Safari&#39;, &#39;Internet Explorer&#39;, &#39;DeepNet Explorer&#39;, &#39;Flock&#39;, &#39;Maxthon&#39;, &#39;Avant Browser&#39;, &#39;AOL&#39;, &#39;Vivaldi&#39;, &#39;UC Browser&#39;, &#39;Yandex Browser&#39;, &#39;Samsung Internet&#39;, &#39;other&#39;)</td><td>Yes</td><td>Visitor&#39;s browser name</td></tr><tr><td><code>os</code></td><td>ENUM(&#39;Linux&#39;, &#39;Windows 11&#39;, &#39;Windows 10&#39;, &#39;Mac OS X&#39;, &#39;Android&#39;, &#39;iOS&#39;, &#39;Windows 8.1&#39;, &#39;Windows 8&#39;, &#39;Windows 7&#39;, &#39;Windows Vista&#39;, &#39;Windows Server 2003/XP x64&#39;, &#39;Windows XP&#39;, &#39;Windows 2000&#39;, &#39;Windows ME&#39;, &#39;Windows 98&#39;, &#39;Windows 95&#39;, &#39;Windows CE&#39;, &#39;Windows (iPhone/iPad)&#39;, &#39;Mac OS&#39;, &#39;Ubuntu&#39;, &#39;Linux Mint&#39;, &#39;Debian&#39;, &#39;Fedora&#39;, &#39;Red Hat&#39;, &#39;SuSE&#39;, &#39;webOS&#39;, &#39;BlackBerry&#39;, &#39;Symbian&#39;, &#39;FreeBSD&#39;, &#39;OpenBSD&#39;, &#39;NetBSD&#39;, &#39;SunOS&#39;, &#39;OpenSolaris&#39;, &#39;Chrome OS&#39;, &#39;bot&#39;)</td><td>Yes</td><td>Visitor&#39;s operating system</td></tr><tr><td><code>engine</code></td><td>ENUM(&#39;google&#39;, &#39;bing&#39;, &#39;yahoo&#39;, &#39;yandex&#39;, &#39;baidu&#39;, &#39;duckduckgo&#39;, &#39;ask&#39;, &#39;aol&#39;, &#39;naver&#39;, &#39;ecosia&#39;)</td><td>Yes</td><td>Search engine identified as the referral source, if detected</td></tr><tr><td><code>version</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Browser version</td></tr><tr><td><code>display</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Screen resolution information</td></tr><tr><td><code>keywords</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Search term identified from search engine parameters</td></tr><tr><td><code>referer</code></td><td>VARCHAR(255)</td><td>Yes</td><td>URL of the referring page or site</td></tr><tr><td><code>is_mobile</code></td><td>TINYINT(1)</td><td>No</td><td>Specifies whether the visit came from a mobile device</td></tr><tr><td><code>page</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Route name of the current or most recently visited page</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Record creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Last record update time</td></tr></tbody></table><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="engines" tabindex="-1"><code>$engines</code> <a class="header-anchor" href="#engines" aria-label="Permalink to “$engines”">​</a></h3><p>Specifies the list of detectable search engines and the parameters associated with their search terms.</p><h3 id="browserlist" tabindex="-1"><code>$browserList</code> <a class="header-anchor" href="#browserlist" aria-label="Permalink to “$browserList”">​</a></h3><p>Specifies the list of patterns used to identify browsers from User-Agent information.</p><h3 id="oslist" tabindex="-1"><code>$osList</code> <a class="header-anchor" href="#oslist" aria-label="Permalink to “$osList”">​</a></h3><p>Specifies the list of patterns used to identify operating systems from User-Agent information.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>The <code>browser</code> and <code>os</code> fields are of type <code>ENUM</code>; their stored values are limited to the options defined in the table structure.</li><li>Browser, operating system, and search engine detection depends on the information sent with the request and the detection patterns; therefore, the result may not always be accurate.</li><li>The <code>keywords</code> field can be used only when the search term can be extracted from the available information.</li><li>The <code>page</code> field stores the Route name, not necessarily the full page URL.</li><li>The table has no dedicated indexes for IP, date, or other statistical fields; if the data volume grows, query patterns should be considered when designing indexes.</li></ul>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};